<!--vbase-->
<template>
  <CodeEditor
    v-model="scriptData"
    language="python"
    :read-only="makeReadOnly"
    :format-code="formatCode"
    :placeholder="seedExample ? exampleScript : ''"
    @formatComplete="(v) => $emit('formatComplete', v)"
    ref="codeEditor"
  />
</template>

<script>
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { useDocScriptStore } from 'src/store/main';
import CodeEditor from 'src/components/common/CodeEditor.vue';

export default defineComponent({
  components: { CodeEditor },
  props: {
    formatCode: {
      type: Boolean,
      required: true,
    },
    makeReadOnly: {
      type: Boolean,
      required: true,
    },
    // CodeEditor auto-fills its `placeholder` into the model whenever the model
    // is empty. That is what we want for a brand-new script (the user starts
    // from the template), but NOT when an existing script is being loaded: the
    // child mounts before the parent's fetch resolves, so on a denied/failed
    // load the boilerplate would be written into script_data and left on
    // screen, looking like leaked foreign code. Callers loading an existing
    // record pass false. Defaults to true so other callers are unaffected.
    seedExample: {
      type: Boolean,
      default: true,
    },
  },
  emits: ['formatComplete'],
  data() {
    return {
      exampleScript: this.buildExampleScript(),
    };
  },
  mounted() {
    window.pyCodeEditor = this;
  },
  computed: {
    scriptData: {
      get() {
        return this.current_model['script_data'] || '';
      },
      set(value) {
        this.current_model['script_data'] = value;
      },
    },
  },
  methods: {
    buildExampleScript() {
      return [
        '##########################################################################',
        '# Author: [Person Name]',
        '# Date Created: [Date/Time]',
        '# Date Updated: [Date/Time]',
        '# Ticket Number: [FELLOWPRO Jira Ticket Number]',
        '# Script Description: [Description of the script]',
        '#',
        '#',
        '# Change History:',
        '# ------------------------------------------------------------------------',
        '# Date        | Author    | Ticket ID | Description',
        '# 2024-05-10  | John Doe  | INC-12345 | Initial script creation',
        '# 2024-06-01  | Jane Smith| CHG-67890 | Added log rotation logic',
        '# ------------------------------------------------------------------------',
        '##########################################################################',
        '',
        "po_number = get_field_value(document_data, 'purchase_order', None)",
        'if not po_number:',
        "    po_number = ''",
        '',
      ].join('\n');
    },
  },
  setup() {
    const doc_script = useDocScriptStore();
    const { current_model } = storeToRefs(doc_script);

    return {
      current_model,
    };
  },
});
</script>
