<template>
  <div class="custom-drawer">
    <div class="version-drawer-header">
      <p class="version-drawer-title">{{ $t('script_history').toUpperCase() }}</p>
      <span class="version-drawer-close" @click="$emit('closeSideBar')">
        <Icon icon="mdi:close" width="22" height="22" />
      </span>
    </div>

    <div class="version-drawer-body" v-if="scriptVersions.success">
      <div
        v-for="(data, key) in scriptVersions.data"
        :key="key"
        class="version-box"
        :class="{ 'version-selected': data.id === selectedVersionId }"
        @click="loadScriptVersion(data.id)"
      >
        <!-- Top row: version + date + status badge -->
        <div class="version-box__top">
          <div class="version-box__left">
            <span class="version-tag">v{{ data.version }}</span>
            <span class="version-date">
              {{ formatDateAccordingToPreference(data.last_modified_on) }}
            </span>
          </div>

          <div class="version-box__badges">
            <q-badge
              :color="status_color_codes['draft']"
              v-if="data.is_draft == true"
              class="version-status-badge"
            >
              {{ $t('draft').toUpperCase() }}
            </q-badge>
            <q-badge
              :color="status_color_codes['active']"
              v-if="data.is_active == true"
              class="version-status-badge"
            >
              {{ $t('active').toUpperCase() }}
            </q-badge>
            <q-badge
              :color="status_color_codes['approved']"
              v-if="data.is_approved == true"
              class="version-status-badge"
            >
              {{ $t('approved').toUpperCase() }}
            </q-badge>
          </div>
        </div>

        <!-- Middle row: author + actions -->
        <div class="version-box__bottom">
          <div class="version-author">
            <q-icon name="person" size="16px" class="q-mr-xs" />
            {{ data.created_by }}
          </div>

          <div class="version-box__actions">
            <q-btn
              flat
              dense
              round
              icon="check"
              size="sm"
              :disable="processing || data.is_active"
              :loading="busyAction === `markAsActive:${data.id}`"
              @click.stop="onMarkAsActiveClick(data.id)"
            >
              <q-tooltip>{{ $t('mark_as_active') }}</q-tooltip>
            </q-btn>
            <q-btn
              v-if="!data.is_active && !data.is_approved && !isDefaultScript"
              flat
              dense
              round
              icon="restore"
              size="sm"
              :disable="processing"
              :loading="busyAction === `restoreVersion:${data.id}`"
              @click.stop="restoreVersion(data.id, data.version)"
              data-test="restore-version-btn"
            >
              <q-tooltip>{{ $t('restore_version') }}</q-tooltip>
            </q-btn>
            <q-btn
              flat
              dense
              round
              icon="edit"
              size="sm"
              :disable="processing"
              :loading="busyAction === `createDraft:${data.id}`"
              @click.stop="createDraft(data.id)"
            >
              <q-tooltip>{{ $t('create_draft') }}</q-tooltip>
            </q-btn>
            <q-btn
              flat
              dense
              round
              icon="delete"
              size="sm"
              color="negative"
              :disable="processing"
              :loading="busyAction === `deleteDraft:${data.id}`"
              @click.stop="deleteDraft(data.id)"
              v-if="data.is_draft && scriptVersions.data.length > 1"
            >
              <q-tooltip>{{ $t('delete_draft') }}</q-tooltip>
            </q-btn>
          </div>
        </div>
      </div>
    </div>

    <div v-else class="version-drawer-empty">
      {{ $t('no_data_found') }}
    </div>

    <q-dialog v-model="confirmActivateOpen" persistent>
      <q-card style="min-width: 320px">
        <q-card-section class="row items-center q-pb-none">
          <q-icon name="warning" color="warning" size="sm" class="q-mr-sm" />
          <span class="text-h6">{{ $t('change_lost_warning') }}</span>
        </q-card-section>

        <q-card-actions align="right">
          <q-btn
            flat
            :label="$t('cancel')"
            color="primary"
            v-close-popup
            @click="cancelActivate"
          />
          <q-btn
            unelevated
            :label="$t('proceed')"
            color="primary"
            v-close-popup
            @click="confirmActivate"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import dateUtils from 'src/utils/date';
import { status_color_codes } from 'src/constants';
import type { ApiResponse } from 'src/@types/api-responses';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  mixins: [dateUtils],
  props: {
    scriptVersions: {
      type: Object as () => ApiResponse<any[]>,
      required: true,
    },
    processing: {
      type: Boolean,
      default: false,
    },
    isDefaultScript: {
      type: Boolean,
      default: false,
    },
    selectedVersionId: {
      type: [String, Number],
      default: null,
    },
    hasUnsavedChanges: {
      type: Boolean,
      default: false,
    },
  },

  data() {
    return {
      menuVisible: false,
      busyAction: '' as string,
      confirmActivateOpen: false,
      pendingActivateId: null as any,
    };
  },
  watch: {
    processing(val: boolean) {
      if (!val) this.busyAction = '';
    },
  },
  methods: {
    loadScriptVersion(id: any) {
      this.$emit('scriptVersionSelected', id);
    },
    onMarkAsActiveClick(id: any) {
      const matchedVersion = this.scriptVersions?.data?.find(
        (version: { id: any }) => version.id == id,
      );
      if (matchedVersion?.is_active) {
        notify.error(this.$t('version_already_active'));
        return;
      }
      if (this.hasUnsavedChanges) {
        this.pendingActivateId = id;
        this.confirmActivateOpen = true;
        return;
      }
      this.markAsActive(id);
    },
    markAsActive(id: any) {
      this.busyAction = `markAsActive:${id}`;
      this.$emit('markAsActive', id);
    },
    confirmActivate() {
      const id = this.pendingActivateId;
      this.pendingActivateId = null;
      if (id !== null) this.markAsActive(id);
    },
    cancelActivate() {
      this.pendingActivateId = null;
    },
    createDraft(id: any) {
      this.busyAction = `createDraft:${id}`;
      this.$emit('createDraft', id);
    },
    deleteDraft(id: any) {
      this.busyAction = `deleteDraft:${id}`;
      this.$emit('deleteDraft', id);
    },
    restoreVersion(id: any, version: number) {
      this.$emit('restoreVersion', id, version);
    },
  },
  setup() {
    return {
      status_color_codes,
    };
  },
});
</script>

