<!--vbase-->
<template>
  <div
    class="page-wrapper q-pr-sm"
    :class="{ shrinked: showHistory && !showAiChat, 'ai-chat-open': showAiChat }"
    :style="showAiChat ? { '--ai-chat-width': aiChatWidth + 'px' } : {}"
  >
        <div v-if="isScriptReadOnly" class="row justify-end q-mb-sm">
          <q-banner dense class="bg-warning text-white">
            <template v-slot:avatar>
              <q-icon name="lock" color="white" size="xs" />
            </template>
            {{ $t('published_version_cannot_be_edited') }}
          </q-banner>
        </div>
    <q-card flat bordered class="import-container white-back">
      <q-card-section>
        <div class="row no-wrap items-center">
            <div class="col q-ml-sm" style="min-width: 120px">
              <q-input
                v-model="current_model['label']"
                outlined
                dense
                :label="$t('name')"
                class="back-white"
                :readonly="isScriptReadOnly"
              />
            </div>

            <div class="col q-ml-sm" style="min-width: 120px">
              <q-select
                clearable
                outlined
                v-model="current_model['doc_type']"
                use-input
                fill-input
                hide-selected
                :options="filterDocTypeList"
                :label="$t('document_type')"
                @filter="filterDocTypeListEvent"
                @update:model-value="current_model['sub_doc_type'] = ''"
                :loading="doc_type_loading"
                emit-value
                map-options
                dense
                class="back-white"
                :readonly="isScriptReadOnly"
              />
            </div>

            <div class="col-auto q-ml-sm" style="min-width: 100px">
              <q-select
                v-model="current_model.trigger_on"
                outlined
                :label="$t('trigger_on')"
                :options="triggerOptions"
                emit-value
                map-options
                dense
                class="back-white"
                :readonly="isScriptReadOnly"
                style="min-width: 100px"
              />
            </div>

            <div class="col q-ml-sm" style="min-width: 120px">
              <q-select
                clearable
                outlined
                :label="$t('sub_type')"
                v-model="current_model['sub_doc_type']"
                use-input
                fill-input
                hide-selected
                :options="SubDocTypeFilteredList"
                @filter="SubDocTypeFilterEvent"
                emit-value
                map-options
                dense
                class="back-white"
                :readonly="isScriptReadOnly"
              />
            </div>

          <div
            class="button-group q-ml-sm"
            style="
              display: flex;
              align-items: center;
              gap: 2px;
            "
          >
            <q-btn
              flat
              round
              size="sm"
              @click="loadLastSelectedScript"
              v-if="lastSelectedScript.id && !makeReadOnly && !isDefaultScript"
              class="script-action-btn"
            >
              <q-icon
                name="refresh"
                style="font-size: 20px; transform: scaleX(-1)"
              />
              <q-tooltip> {{ $t('reset_script') }} </q-tooltip>
            </q-btn>
            <q-btn
              flat
              round
              size="sm"
              @click="formatCode"
              v-if="lastSelectedScript.id"
              class="script-action-btn"
            >
              <q-icon name="brush" style="font-size: 20px" />
              <q-tooltip> {{ $t('format_button') }} </q-tooltip>
            </q-btn>
            <q-btn
              flat
              round
              size="sm"
              @click="saveRecord"
              :disable="processing"
              v-if="!isDefaultScript && ((lastSelectedScript.id && (lastSelectedScript.is_draft || !makeReadOnly)) || (!current_model['id'] && !record_id))"
              class="script-action-btn"
              color="primary"
            >
              <q-spinner v-if="processing" size="20px" />
              <q-icon v-else name="save" style="font-size: 20px" />
              <q-tooltip> {{ $t('save') }} </q-tooltip>
            </q-btn>

            <q-separator vertical inset class="q-mx-xs" style="height: 24px" />

            <q-btn
              flat
              round
              size="sm"
              @click="toggleAiChat"
              :color="showAiChat ? 'primary' : 'grey-7'"
              :disable="!hasDocNetSubscription"
              class="script-action-btn"
              data-testid="script-ai-chat-toggle"
            >
              <q-icon name="smart_toy" size="20px" />
              <q-tooltip>{{
                hasDocNetSubscription
                  ? $t('ai_chat_tooltip')
                  : $t('ai_chat_docnet_required_tooltip')
              }}</q-tooltip>
            </q-btn>
            <q-btn
              flat
              round
              size="sm"
              @click="toggleHistory"
              v-if="showVersion"
              :color="showHistory ? 'primary' : 'grey-7'"
              class="script-action-btn"
            >
              <q-icon name="history" size="20px" />
              <q-tooltip>{{ showHistory ? $t('hide_script_history') : $t('show_script_history') }}</q-tooltip>
            </q-btn>
          </div>
        </div>
      </q-card-section>

      <q-card-section
        v-if="accessDenied"
        class="column items-center justify-center editor-height"
        data-testid="script-access-denied"
      >
        <q-icon name="lock" size="48px" color="grey-6" />
        <div class="text-h6 q-mt-md">{{ $t('no_access') }}</div>
        <div class="text-body2 text-grey-7 q-mt-xs">
          {{ $t('NOT_AUTHORIZED') }}
        </div>
      </q-card-section>
      <q-card-section v-else class="row items-center editor-height">
        <editor
          :formatCode="is_format_code"
          @formatComplete="afterFormatted"
          :makeReadOnly="makeReadOnly || isDefaultScript"
          :seedExample="record_id === ''"
        ></editor
      ></q-card-section>

      <q-card-section
        class="row items-center q-pb-none full-width"
        style="min-height: 100px"
        v-if="display_output_view"
      >
        <div class="col-1">Result:</div>
        <pre class="col-11 bg-grey-3 script-output">{{ script_output }}</pre>
      </q-card-section>

      <Loader />
    </q-card>
  </div>
  <transition name="slide-drawer">
    <versionDrawer
      :scriptVersions="scriptVersions"
      :processing="processing"
      :isDefaultScript="isDefaultScript"
      :selectedVersionId="lastSelectedScript.id"
      :hasUnsavedChanges="hasUnsavedChanges"
      @scriptVersionSelected="loadSelectedVersion"
      @closeSideBar="showHistory = false"
      @markAsActive="markAsActive"
      @createDraft="createDraftVersion"
      @deleteDraft="deleteDraftVersion"
      @restoreVersion="restoreVersion"
      v-if="showHistory && !accessDenied"
    />
  </transition>
  <transition name="slide-drawer">
    <ScriptAiChat
      v-if="showAiChat && hasDocNetSubscription && !accessDenied"
      v-model:width="aiChatWidth"
      :currentScript="current_model.script_data ? JSON.stringify(current_model.script_data) : ''"
      :docType="current_model.doc_type || selected_doc_type || ''"
      @close="showAiChat = false"
      @copy-to-editor="handleCopyToEditor"
    />
  </transition>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { isDefaultOrg } from 'src/constants';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { docScriptApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { defineComponent, ref, computed } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import ScriptAiChat from 'src/components/ScriptAiChat.vue';
import versionDrawer from 'src/components/versionDrawer.vue';
import { notify } from 'src/components/notifications/notify';
import editor from 'src/components/document/script/editor.vue';
import { useDocScriptStore, useDropdownStore } from 'src/store/main';
import { useSubscriptionStore } from 'src/store/User/subscription.store';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {},
  components: {
    editor,
    Loader,
    versionDrawer,
    ScriptAiChat,
  },
  watch: {
    selected_doc_type: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
    'current_model.script_data': {
      handler: function (newVal, oldVal) {
        // Capture the saved baseline on first load so hasUnsavedChanges is
        // false until the user actually edits something.
        if (this.originalCode === null && newVal) {
          this.originalCode = JSON.stringify(newVal);
          this.originalScriptName = this.current_model.label ?? '';
        }
      },
      deep: true,
    },
  },
  data() {
    return {
      is_format_code: false,
      showHistory: true,
      showAiChat: false,
      aiChatWidth: 350,
      scriptVersions: { data: [] },
      makeReadOnly: true,
      showVersion: false,
      lastSelectedScript: {} as any,
      originalCode: null as string | null,
      originalScriptName: '' as string,
      accessDenied: false,
    };
  },
  computed: {
    hasUnsavedChanges() {
      // Wait until the saved baseline is captured before reporting a diff.
      if (this.originalCode === null) return false;
      const codeChanged =
        JSON.stringify(this.current_model.script_data) !== this.originalCode;
      const labelChanged = this.current_model.label !== this.originalScriptName;
      return codeChanged || labelChanged;
    },
    isDefaultScript() {
      return isDefaultOrg(this.current_model?.org_id);
    },
    isScriptReadOnly(): boolean {
      // Banner appears when editing is disabled for the loaded script version.
      // Default-org scripts are always read-only; otherwise it's a non-draft
      // published version loaded from history.
      if (this.isDefaultScript) return true;
      return Boolean(this.lastSelectedScript.id) && this.makeReadOnly;
    },
    hasDocNetSubscription(): boolean {
      // Script AI Chat is gated on DocNet. Backend enforces this with a 401,
      // frontend hides the toggle so a non-DocNet user never even sees the
      // option. Follows the same pattern as SubscriptionUsage.vue's check.
      return useSubscriptionStore().get_subscribed_apps.includes('DOC_NET');
    },
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    this.reset();
    next();
  },

  mounted: function () {
    this.initView();
  },

  methods: {
    async initView() {
      this.accessDenied = false;
      try {
        await this.getDocTypesSubTypes();
        this.filterDocTypeList = this.doc_type_list;

        if (!this.selected_doc_type) {
          logInfo('selected_doc_type is missing');
          return;
        }
        this.processing = true;

        if (this.record_id === '') {
          this.setEmptyModel();
          this.makeReadOnly = false;
          this.showVersion = false;
          return;
        }

        try {
          await this.getScriptById();
        } catch (err) {
          // Fail closed. The backend denies a cross-org script with a 401 and
          // never returns script_data, but the editor used to stay on screen
          // showing its own placeholder boilerplate — which reads to a tester
          // as if foreign script content had leaked. Wipe the model and swap
          // the editor for an access-denied panel so nothing code-like remains.
          this.accessDenied = true;
          this.setEmptyModel();
          this.current_model.script_data = '';
          this.showVersion = false;
          this.showHistory = false;
          throw err;
        }
        this.filertByDocTypeKey();
        await this.getScriptVersions();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    formatCode() {
      this.is_format_code = true;
    },
    afterFormatted(value: any) {
      this.is_format_code = value;
    },
    async saveRecord() {
      try {
        this.processing = true;
        if (
          this.lastSelectedScript &&
          this.lastSelectedScript.id !== undefined
        ) {
          this.current_model['version_id'] = this.lastSelectedScript.id;
        }
        const response = await this.saveCurrentModel();
        notify.success(this.$t('MSG_SAVE'));
        this.setRouteForEdit();
        await this.getScriptVersions();

        // If a draft was created/updated, set lastSelectedScript so save button stays visible
        if (response && response.draft) {
          this.lastSelectedScript = {
            id: response.draft.id,
            version: response.draft.version,
            is_draft: response.draft.is_draft,
          };
          this.makeReadOnly = false;
        }
        this.originalCode = JSON.stringify(this.current_model['script_data']);
        this.originalScriptName = this.current_model.label;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    setRouteForEdit() {
      if (this.record_id !== '') {
        return;
      }

      const params = {
        doc_type: this.selected_doc_type,
      } as dynamicObj;
      if (this.sub_doc_type_key !== '') {
        params['sub_doc_type_key'] = this.sub_doc_type_key;
      }
      this.$router.push({
        name: 'record-script',
        params,
        query: { id: this.current_model.id },
      });
    },

    filterDocTypeListEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterDocTypeList = this.doc_type_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterDocTypeList = this.doc_type_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    filertByDocTypeKey() {
      if (!this.current_model['doc_type']) {
        this.SubDocTypeFilteredList = [];
        return;
      }

      this.SubDocTypeFilteredList = this.sub_types_list.filter((v: any) => {
        return v.doc_type_key == this.current_model['doc_type'];
      });
    },

    SubDocTypeFilterEvent(val: string, update: any, abort: any) {
      this.filertByDocTypeKey();
      if (!val) {
        update(() => {
          this.filertByDocTypeKey();
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.SubDocTypeFilteredList = this.SubDocTypeFilteredList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
    toggleAiChat() {
      this.showAiChat = !this.showAiChat;
      if (this.showAiChat) this.showHistory = false;
    },
    toggleHistory() {
      this.showHistory = !this.showHistory;
      if (this.showHistory) this.showAiChat = false;
    },
    handleCopyToEditor(code: string) {
      this.current_model.script_data = code;
    },
    loadSelectedVersion(scriptId: any) {
      const matchedVersion = this.scriptVersions?.data?.find(
        (version: { id: any }) => version.id == scriptId,
      );
      if (matchedVersion) {
        this.lastSelectedScript = JSON.parse(JSON.stringify(matchedVersion));
        this.current_model['script_data'] = JSON.parse(
          matchedVersion['script_data'],
        );
        this.current_model['version_id'] = matchedVersion['id'];
        this.makeReadOnly = matchedVersion['is_draft'] ? false : true;
        this.originalCode = JSON.stringify(this.current_model['script_data']);
      }
    },
    loadLastSelectedScript() {
      const matchedVersion = this.scriptVersions?.data?.find(
        (version: { id: any }) => version.id == this.lastSelectedScript.id,
      );
      if (matchedVersion) {
        this.lastSelectedScript = JSON.parse(JSON.stringify(matchedVersion));
        this.current_model['script_data'] = JSON.parse(
          matchedVersion['script_data'],
        );
        this.current_model['version_id'] = matchedVersion['id'];
        this.makeReadOnly = matchedVersion['is_draft'] ? false : true;
        this.originalCode = JSON.stringify(this.current_model['script_data']);
      }
    },
    async getScriptVersions() {
      this.showVersion = true;
      const result = await docScriptApiService.getScriptVersions(
        this.current_model['id'],
      );

      // Transform backend response to match frontend expected format
      // Backend returns: { success, data: { versions: [...], script_id, ... } }
      // Frontend expects: { success, data: [...] } with specific field names
      if (result && result.data && result.data.versions) {
        const transformedVersions = result.data.versions.map((v: any) => ({
          id: v.id,
          version: v.version_number,
          is_active: v.is_active,
          is_draft: v.is_draft,
          is_approved: v.is_approved,
          created_by: v.created_by_name || v.created_by_email,
          last_modified_on: v.last_modified_at,
          script_data: v.script_data,
        }));
        this.scriptVersions = { success: true, data: transformedVersions };

        // Auto-select the active version so buttons appear without opening history
        if (!this.lastSelectedScript.id && transformedVersions.length > 0) {
          const activeVersion = transformedVersions.find((v: any) => v.is_active);
          const selectedVersion = activeVersion || transformedVersions[0];
          this.lastSelectedScript = JSON.parse(JSON.stringify(selectedVersion));
          this.current_model['version_id'] = selectedVersion.id;
          this.makeReadOnly = selectedVersion.is_draft ? false : true;
        }
      } else {
        this.scriptVersions = { success: false, data: [] };
      }

      this.makeReadOnly = this.current_model['is_draft']
        ? false
        : this.makeReadOnly;
    },
    async markAsActive(version_id: number) {
      this.processing = true;
      try {
        await docScriptApiService.markAsActive(version_id);
        await this.getScriptVersions();
        const matchedVersion = this.scriptVersions?.data?.find(
          (version: { id: any }) => version.id == version_id,
        );
        if (matchedVersion) {
          this.current_model['script_data'] = JSON.parse(
            matchedVersion['script_data'],
          );
          this.makeReadOnly = matchedVersion['is_draft'] ? false : true;
        }
        notify.success(this.$t('verion_marked_as_active'));
      } finally {
        this.processing = false;
      }
    },
    async createDraftVersion(version_id: number) {
      this.processing = true;
      try {
        const response = await docScriptApiService.createScriptDraft(version_id);

        if (response.success) {
          await this.getScriptVersions();
          if (response.data?.id) {
            this.loadSelectedVersion(response.data.id);
          }
          notify.success(this.$t('draft_has_been_created'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.processing = false;
      }
    },
    async deleteDraftVersion(version_id: number) {
      this.processing = true;
      try {
        const response = await docScriptApiService.deleteScriptDraft(version_id);
        if (response.success) {
          const wasViewingDeleted = this.lastSelectedScript.id === version_id;
          const versions = this.scriptVersions?.data ?? [];
          const idx = versions.findIndex((v: any) => v.id === version_id);
          if (idx !== -1) versions.splice(idx, 1);

          if (wasViewingDeleted && versions[0]) {
            this.loadSelectedVersion(versions[0].id);
          }
          notify.success(this.$t('draft_has_been_deleted'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.processing = false;
      }
    },
    restoreVersion(scriptId: any, version: number) {
      // Apply the same logic as loadSelectedVersion
      const matchedVersion = this.scriptVersions?.data?.find(
        (v: { id: any }) => v.id == scriptId,
      );
      if (matchedVersion) {
        this.lastSelectedScript = JSON.parse(JSON.stringify(matchedVersion));
        this.current_model['script_data'] = JSON.parse(
          matchedVersion['script_data'],
        );
        this.current_model['version_id'] = matchedVersion['id'];
        this.makeReadOnly = matchedVersion['is_draft'] ? false : true;
        this.originalCode = JSON.stringify(this.current_model['script_data']);
      }
    },
  },
  setup() {
    const doc_script = useDocScriptStore();
    const { getScriptById, saveCurrentModel, setEmptyModel, reset } =
      doc_script;
    const {
      current_model,
      selected_doc_type,
      record_id,
      sub_doc_type_key,
      display_output_view,
      script_output,
      processing,
      is_script_editor_available,
    } = storeToRefs(doc_script);

    const dropdown_store = useDropdownStore();
    const { getDocTypesSubTypes } = dropdown_store;
    const {
      doc_type_list,
      sub_types_list,
      script_trigger_list,
      doc_type_loading,
    } = storeToRefs(dropdown_store);
    const SubDocTypeFilteredList: any = ref([]);
    const filterDocTypeList: any = ref(dropdown_store.doc_type_list);

    // Transform trigger list to use translated labels
    const triggerOptions = computed(() =>
      script_trigger_list.value.map((trigger: string) => ({
        label: i18n.t(`script.${trigger}`.toLocaleLowerCase()),
        value: trigger,
      })),
    );

    return {
      reset,
      setEmptyModel,
      filterDocTypeList,
      sub_types_list,
      SubDocTypeFilteredList,
      doc_type_list,
      doc_type_loading,
      getDocTypesSubTypes,
      record_id,
      sub_doc_type_key,
      is_script_editor_available,
      script_output,
      display_output_view,
      selected_doc_type,
      saveCurrentModel,
      getScriptById,
      current_model,
      processing,
      CalHeight: ref('600'),
      triggerOptions,
    };
  },
});
</script>

<style lang="scss" scoped>
