  display: flex;
  flex-direction: column;
  width: 100%;
  height: calc(100vh - 100px);
  transition: width 0.3s ease;

  // Right-side panels (version drawer / AI chat) are position:fixed at
  // right:0. The parent .settings-content-area has 24px right padding,
  // so the first 24px of the panel overlaps empty padding (not content).
  // Shrink by panelWidth - 24px so content stops exactly at the panel.
  &.shrinked {
    width: calc(100% - 268px); // 292px drawer - 24px parent padding
  }

  // AI chat panel is user-resizable, so its width comes from a CSS variable
  // set inline (--ai-chat-width). Same 24px parent-padding offset applies.
  &.ai-chat-open {
    width: calc(100% - var(--ai-chat-width) + 24px);
  }

  :deep(.import-container) {
    display: flex;
    flex-direction: column;
    width: 100% !important;
    max-width: 100% !important;
    height: 100%;
    margin: 0 !important;
    overflow: hidden;

    > .q-card__section:first-child {
      flex-shrink: 0;
    }
  }

  :deep(.editor-height) {
    flex: 1;
    min-height: 0;
    padding: 0 16px 16px;
    overflow: hidden;

    > * {
      height: 100%;
      overflow-y: auto;
    }
  }
}

.script-action-btn {
  transition: background-color 0.15s ease;

  &:hover {
    background-color: rgba(0, 0, 0, 0.05);
  }
}

.slide-drawer-enter-active,
.slide-drawer-leave-active {
  transition: transform 0.3s ease;
}

.slide-drawer-enter-from,
.slide-drawer-leave-to {
  transform: translateX(100%);
}
</style>
