<template>
  <div class="custom-drawer ai-chat-drawer" :style="{ width: width + 'px' }">
    <div class="resize-handle" @mousedown.prevent="startResize"></div>
    <div class="drawer-space drawer-header">
      <p>{{ $t('ai_assistant').toUpperCase() }}</p>
      <span class="q-mb-md close-icon" @click="$emit('close')">
        <Icon icon="mdi:close" width="24" height="24" />
      </span>
    </div>

    <div class="chat-messages" ref="messagesContainer">
      <template v-for="(msg, idx) in messages" :key="idx">
        <div
          class="chat-bubble"
          :class="msg.role === 'user' ? 'chat-bubble--user' : 'chat-bubble--assistant'"
        >
          <div v-if="msg.role === 'assistant'" class="assistant-content">
            <template v-for="(block, bIdx) in parseContent(msg.content)" :key="bIdx">
              <pre v-if="block.type === 'code'" class="code-block">
                <div class="code-block-header">
                  <span>{{ block.lang || 'python' }}</span>
                  <q-btn
                    flat
                    dense
                    size="xs"
                    icon="content_copy"
                    @click="$emit('copy-to-editor', block.code)"
                  >
                    <q-tooltip>{{ $t('copy_to_editor') }}</q-tooltip>
                  </q-btn>
                </div>
                <code>{{ block.code }}</code>
              </pre>
              <span v-else v-html="block.html"></span>
            </template>
          </div>
          <div v-else>{{ msg.content }}</div>
        </div>
        <div v-if="msg.usage" class="token-usage">
          <Icon icon="mdi:chart-bar" width="14" height="14" />
          <span>{{ msg.usage.prompt_tokens }} in · {{ msg.usage.completion_tokens }} out · {{ msg.usage.total_tokens }} total</span>
        </div>
      </template>

      <div v-if="isStreaming" class="chat-bubble chat-bubble--assistant">
        <div class="assistant-content">
          <template v-for="(block, bIdx) in parseContent(streamingContent)" :key="bIdx">
            <pre v-if="block.type === 'code'" class="code-block">
              <div class="code-block-header">
                <span>{{ block.lang || 'python' }}</span>
                <q-btn
                  flat
                  dense
                  size="xs"
                  icon="content_copy"
                  @click="$emit('copy-to-editor', block.code)"
                >
                  <q-tooltip>{{ $t('copy_to_editor') }}</q-tooltip>
                </q-btn>
              </div>
              <code>{{ block.code }}</code>
            </pre>
            <span v-else v-html="block.html"></span>
          </template>
          <span class="typing-cursor">|</span>
        </div>
      </div>
      <div v-if="isStreaming && lastUsage" class="token-usage">
        <Icon icon="mdi:chart-bar" width="14" height="14" />
        <span>{{ lastUsage.prompt_tokens }} in · {{ lastUsage.completion_tokens }} out · {{ lastUsage.total_tokens }} total</span>
      </div>
    </div>

    <div class="chat-input-area">
      <q-input
        v-model="userInput"
        outlined
        dense
        :placeholder="$t('ai_chat_placeholder')"
        @keyup.enter="sendMessage"
        :disable="isStreaming"
        class="chat-input"
      >
        <template v-slot:append>
          <q-btn
            flat
            dense
            round
            icon="send"
            :disable="!userInput.trim() || isStreaming"
            @click="sendMessage"
            color="primary"
          />
        </template>
      </q-input>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, nextTick } from 'vue';

import { api, getAuthorizationToken } from 'src/pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';

export interface TokenUsage {
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
}

export interface ChatMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
  usage?: TokenUsage;
}

export interface ContentBlock {
  type: 'text' | 'code';
  html?: string;
  code?: string;
  lang?: string;
}

const SYSTEM_PROMPT = `You are a DocBits scripting assistant. You help users write Python scripts for document processing.

Available helper functions:
- get_field_value(field_name, document_data) - Get a field's value
- set_field_value(field_name, value, document_data) - Set a field's value
- get_field_by_name(field_name, document_data) - Get full field object
- get_table_field_value(table_name, row_index, column_name, document_data) - Get table cell value
- set_table_field_value(table_name, row_index, column_name, value, document_data) - Set table cell value
- get_table_rows(table_name, document_data) - Get all rows from a table
- add_table_row(table_name, row_data, document_data) - Add a row to a table
- delete_table_row(table_name, row_index, document_data) - Delete a table row

The script receives 'document_data' as input containing all document fields and tables.
Always provide complete, working Python code examples. Use code blocks with python syntax.`;

export default defineComponent({
  name: 'ScriptAiChat',
  
  props: {
    currentScript: {
      type: String,
      default: '',
    },
    docType: {
      type: String,
      default: '',
    },
    width: {
      type: Number,
      default: 350,
    },
  },
  emits: ['close', 'copy-to-editor', 'update:width'],
  setup(props, { emit }) {
    const messages = ref<ChatMessage[]>([]);
    const userInput = ref('');
    const isStreaming = ref(false);
    const streamingContent = ref('');
    const messagesContainer = ref<HTMLElement | null>(null);
    const lastUsage = ref<TokenUsage | null>(null);

    function scrollToBottom() {
      nextTick(() => {
        if (messagesContainer.value) {
          messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
        }
      });
    }

    function parseContent(content: string): ContentBlock[] {
      if (!content) return [{ type: 'text', html: '' }];

      const blocks: ContentBlock[] = [];
      const codeRegex = /```(\w*)\n?([\s\S]*?)```/g;
      let lastIndex = 0;
      let match;

      while ((match = codeRegex.exec(content)) !== null) {
        if (match.index > lastIndex) {
          const text = content.slice(lastIndex, match.index);
          blocks.push({
            type: 'text',
            html: escapeHtml(text).replace(/\n/g, '<br>'),
          });
        }
        blocks.push({
          type: 'code',
          lang: match[1] || 'python',
          code: match[2].trim(),
        });
        lastIndex = match.index + match[0].length;
      }

      if (lastIndex < content.length) {
        const text = content.slice(lastIndex);
        blocks.push({
          type: 'text',
          html: escapeHtml(text).replace(/\n/g, '<br>'),
        });
      }

      return blocks.length ? blocks : [{ type: 'text', html: escapeHtml(content).replace(/\n/g, '<br>') }];
    }

    function escapeHtml(text: string): string {
      const map: Record<string, string> = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;',
      };
      return text.replace(/[&<>"']/g, (c) => map[c]);
    }

    async function sendMessage() {
      const input = userInput.value.trim();
      if (!input || isStreaming.value) return;

      messages.value.push({ role: 'user', content: input });
      userInput.value = '';
      scrollToBottom();

      isStreaming.value = true;
      streamingContent.value = '';
      lastUsage.value = null;

      try {
        const token = await getAuthorizationToken();
        const orgId = getOrgId();

        const apiMessages: ChatMessage[] = [
          { role: 'system', content: SYSTEM_PROMPT },
          ...messages.value,
        ];

        const url = api.scriptAiChat;

        const response = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': token || '',
            'X-ORG-ID': orgId || '',
          },
          body: JSON.stringify({
            messages: apiMessages.map((m) => ({
              role: m.role,
              content: m.content,
            })),
            context: {
              doc_type: props.docType,
              current_script: props.currentScript,
            },
          }),
        });

        if (!response.ok) {
          const statusMessages: Record<number, string> = {
            404: 'AI Chat is not available yet. The endpoint may not be deployed.',
            401: 'Authentication failed. Please refresh the page and try again.',
            503: 'AI service is temporarily unavailable. Please try again later.',
          };
          throw new Error(
            statusMessages[response.status] ||
              `Something went wrong (HTTP ${response.status}). Please try again.`,
          );
        }

        const reader = response.body?.getReader();
        if (!reader) throw new Error('No response body');

        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (!line.startsWith('data: ')) continue;
            const data = line.slice(6);
            if (data === '[DONE]') continue;

            try {
              const parsed = JSON.parse(data);
              if (parsed.error) {
                throw new Error(
                  parsed.error.message || 'An error occurred during streaming.',
                );
              }
              if (parsed.usage) {
                lastUsage.value = parsed.usage;
                scrollToBottom();
                continue;
              }
              const delta = parsed.choices?.[0]?.delta?.content;
              if (delta) {
                streamingContent.value += delta;
                scrollToBottom();
              }
            } catch (parseErr: any) {
              if (parseErr instanceof SyntaxError) continue; // skip malformed SSE chunks
              throw parseErr; // re-throw stream errors
            }
          }
        }

        if (streamingContent.value) {
          messages.value.push({
            role: 'assistant',
            content: streamingContent.value,
            ...(lastUsage.value ? { usage: lastUsage.value } : {}),
          });
        }
      } catch (err: any) {
        messages.value.push({
          role: 'assistant',
          content: `Error: ${err.message || 'Failed to get response'}`,
        });
      } finally {
        isStreaming.value = false;
        streamingContent.value = '';
        scrollToBottom();
      }
    }

    function startResize(e: MouseEvent) {
      const startX = e.clientX;
      const startWidth = props.width;
      const onMouseMove = (ev: MouseEvent) => {
        const newWidth = Math.min(700, Math.max(280, startWidth + (startX - ev.clientX)));
        emit('update:width', newWidth);
      };
      const onMouseUp = () => {
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
      };
      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    }

    return {
      messages,
      userInput,
      isStreaming,
      streamingContent,
      messagesContainer,
      lastUsage,
      sendMessage,
      parseContent,
      startResize,
    };
  },
});
</script>

