<!--vbase-->
<template>
  <div class="script-record-wrapper">
    <template v-if="load_script">
      <settingsEditor />
    </template>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDocScriptStore } from 'src/store/main';
import { isUndefinedOrNull } from 'src/utils/general';
import settingsEditor from 'src/pages/Settings/Components/Scripts/edit-create.vue';

export default defineComponent({
  el: '#app',
  mixins: [],
  props: {},
  components: {
    settingsEditor,
  },
  data() {
    return {};
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    initView() {
      this.load_script = false;
      this.reset();

      if (!isUndefinedOrNull(this.$route.params.sub_doc_type_key)) {
        this.sub_doc_type_key = String(
          this.$route.params.sub_doc_type_key || '',
        );
      }

      if (this.$route.query && !isUndefinedOrNull(this.$route.query.id)) {
        this.record_id = String(this.$route.query.id || '');
      }
      this.selected_doc_type = String(this.$route.params.doc_type || '');
      this.load_script = true;
    },
  },
  setup() {
    const doc_script = useDocScriptStore();
    const { selected_doc_type, sub_doc_type_key, record_id } =
      storeToRefs(doc_script);
    const { reset } = doc_script;

    return {
      reset,
      record_id,
      selected_doc_type,
      sub_doc_type_key,
      load_script: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.script-record-wrapper {
  width: 100%;
  height: 100%;
}
</style>
